mapper.select:
SELECT t.ticket_id, t.ticket_no, t.ticket_title, t.ticket_type, t.dept_id, t.owner_user_id, t.status, t.remark, t.create_time FROM biz_ticket t
AND t.ticket_no LIKE CONCAT('%', #{ticketNo}, '%')
AND t.ticket_title LIKE CONCAT('%', #{ticketTitle}, '%')
AND t.ticket_type = #{ticketType}
AND t.status = #{status}
ORDER BY t.ticket_id ASC

mapper.update:
UPDATE biz_ticket
ticket_title = #{ticketTitle}, ticket_no = #{ticketNo}, ticket_type = #{ticketType}, dept_id = #{deptId}, owner_user_id = #{ownerUserId}, status = #{status}, remark = #{remark},
WHERE ticket_id = #{ticketId}
